CREATE TABLE "Property" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"type" TEXT NOT NULL,"location" TEXT NOT NULL,"price" INTEGER,"status" TEXT NOT NULL DEFAULT 'available',"area" DOUBLE PRECISION NOT NULL,"landArea" DOUBLE PRECISION NOT NULL,"bedrooms" INTEGER NOT NULL,"floors" INTEGER NOT NULL,"readiness" TEXT NOT NULL,"finish" TEXT NOT NULL,"seaDistance" DOUBLE PRECISION NOT NULL,"description" TEXT NOT NULL,"utilities" TEXT[] NOT NULL,"published" BOOLEAN NOT NULL DEFAULT false,"featured" BOOLEAN NOT NULL DEFAULT false,"demo" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Property_published_status_idx" ON "Property"("published","status");
CREATE TABLE "PropertyImage" ("id" TEXT PRIMARY KEY,"propertyId" TEXT NOT NULL REFERENCES "Property"("id") ON DELETE CASCADE ON UPDATE CASCADE,"file" TEXT NOT NULL,"alt" TEXT NOT NULL,"order" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Lead" ("id" TEXT PRIMARY KEY,"propertyId" TEXT REFERENCES "Property"("id") ON DELETE SET NULL ON UPDATE CASCADE,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"comment" TEXT NOT NULL DEFAULT '',"consent" BOOLEAN NOT NULL,"consentVersion" TEXT NOT NULL DEFAULT '2026-09-14',"status" TEXT NOT NULL DEFAULT 'new',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Lead_status_createdAt_idx" ON "Lead"("status","createdAt");
CREATE TABLE "AdminUser" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL);
